package com.alpharip.staffmod.IncidentPostMortemBoard; import java.util.*;
public final class IncidentPostMortemService {
 private final IncidentPostMortemBoard board;public IncidentPostMortemService(IncidentPostMortemBoard b){if(b==null)throw new IllegalArgumentException("Board required");board=b;}
 public IncidentRecord create(String t,String d,IncidentCategory c,IncidentSeverity s,String p,long n){IncidentPostMortemValidator.validate(t,d,p);IncidentRecord r=new IncidentRecord(t,d,c,s,p,n);board.add(r);return r;}
 public void setStatus(String id,IncidentStatus s,long n){get(id).setStatus(s,n);} public void assign(String id,String a,String actor,long n){get(id).assign(a,actor,n);} public void addTimeline(String id,String actor,String text,long n){get(id).addTimeline(new IncidentTimelineEntry(UUID.randomUUID().toString(),actor,text,n));}
 public void setRootCause(String id,String s,String f,String o,long n){get(id).setRootCause(new IncidentRootCause(s,f,o,n));} public void setImpact(String id,String s,String u,String d,int v,long n){get(id).setImpact(new IncidentImpact(s,u,d,v,n));}
 public void addAction(String id,String t,String d,String a,long n){get(id).addAction(new IncidentAction(t,d,a,n));} public void addLesson(String id,String l,String c,String a,long n){get(id).addLesson(new IncidentLesson(UUID.randomUUID().toString(),l,c,a,n));} public boolean remove(String id){return board.remove(id);}
 public List<IncidentRecord> filter(IncidentPostMortemFilter f,final IncidentPostMortemSort mode){List<IncidentRecord> out=new ArrayList<IncidentRecord>();for(IncidentRecord r:board.getAll())if(f==null||f.matches(r))out.add(r);Collections.sort(out,new Comparator<IncidentRecord>(){public int compare(IncidentRecord a,IncidentRecord b){IncidentPostMortemSort m=mode==null?IncidentPostMortemSort.NEWEST:mode;switch(m){case OLDEST:return Long.compare(a.getCreatedAt(),b.getCreatedAt());case SEVERITY:return Integer.compare(b.getSeverity().ordinal(),a.getSeverity().ordinal());case LAST_UPDATED:return Long.compare(b.getUpdatedAt(),a.getUpdatedAt());default:return Long.compare(b.getCreatedAt(),a.getCreatedAt());}}});return out;}
 public IncidentPostMortemSummary summarize(){int o=0,i=0,a=0,r=0,c=0,u=0;for(IncidentRecord x:board.getAll()){switch(x.getStatus()){case OPEN:o++;break;case INVESTIGATING:i++;break;case ACTION_REQUIRED:a++;break;case RESOLVED:case CLOSED:r++;break;}if(x.getSeverity()==IncidentSeverity.CRITICAL)c++;for(IncidentAction action:x.getActions())if(!action.isCompleted())u++;}return new IncidentPostMortemSummary(board.size(),o,i,a,r,c,u);}
 private IncidentRecord get(String id){IncidentRecord r=board.get(id);if(r==null)throw new IllegalArgumentException("Incident not found: "+id);return r;}
}